package com.cloudcart.security;
import com.cloudcart.entity.Entities.User;import com.cloudcart.repository.UserRepository;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.stereotype.Component;import javax.crypto.SecretKey;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.util.*;
@Component public class JwtFilter extends org.springframework.web.filter.OncePerRequestFilter {private final UserRepository users;private final SecretKey key;public JwtFilter(UserRepository users,@Value("${app.jwt-secret}")String secret){this.users=users;this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));}public String issue(User u){return Jwts.builder().subject(u.email).claim("role",u.role.name()).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+86400000)).signWith(key).compact();}@Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{try{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer ")){String email=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload().getSubject();User u=users.findByEmail(email).orElseThrow();var auth=new UsernamePasswordAuthenticationToken(u.email,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.role)));org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(auth);}}catch(Exception ex){org.springframework.security.core.context.SecurityContextHolder.clearContext();}chain.doFilter(req,res);}}
